/* Class-only adapter of pmndrs/drei v10.7.7. React/FBO integration is caller-owned. */
(function () {
  'use strict';
  const THREE = window.PortfolioR3F;

class MeshTransmissionMaterialImpl extends THREE.GlassPhysicalMaterial {
  constructor(samples = 4, transmissionSampler = false) {
    super()

    this.uniforms = {
      chromaticAberration: { value: 0.05 },
      // Transmission must always be 0, unless transmissionSampler is being used
      transmission: { value: 0 },
      // Instead a workaround is used, see below for reasons why
      _transmission: { value: 1 },
      transmissionMap: { value: null },
      // Roughness is 1 in THREE.MeshPhysicalMaterial but it makes little sense in a transmission material
      roughness: { value: 0 },
      thickness: { value: 0 },
      thicknessMap: { value: null },
      attenuationDistance: { value: Infinity },
      attenuationColor: { value: new THREE.Color('white') },
      anisotropicBlur: { value: 0.1 },
      time: { value: 0 },
      distortion: { value: 0.0 },
      distortionScale: { value: 0.5 },
      temporalDistortion: { value: 0.0 },
      buffer: { value: null },
    }

    this.onBeforeCompile = (shader) => {
      shader.uniforms = {
        ...shader.uniforms,
        ...this.uniforms,
      }

      // Fix for r153-r156 anisotropy chunks
      // https://github.com/mrdoob/three.js/pull/26716
      if (this.anisotropy > 0) shader.defines.USE_ANISOTROPY = ''

      // If the transmission sampler is active inject a flag
      if (transmissionSampler) shader.defines.USE_SAMPLER = ''
      // Otherwise we do use use .transmission and must therefore force USE_TRANSMISSION
      // because threejs won't inject it for us
      else shader.defines.USE_TRANSMISSION = ''

      // Head
      shader.fragmentShader =
        /*glsl*/ `
      uniform float chromaticAberration;         
      uniform float anisotropicBlur;      
      uniform float time;
      uniform float distortion;
      uniform float distortionScale;
      uniform float temporalDistortion;
      uniform sampler2D buffer;

      vec3 random3(vec3 c) {
        float j = 4096.0*sin(dot(c,vec3(17.0, 59.4, 15.0)));
        vec3 r;
        r.z = fract(512.0*j);
        j *= .125;
        r.x = fract(512.0*j);
        j *= .125;
        r.y = fract(512.0*j);
        return r-0.5;
      }

      uint hash( uint x ) {
        x += ( x << 10u );
        x ^= ( x >>  6u );
        x += ( x <<  3u );
        x ^= ( x >> 11u );
        x += ( x << 15u );
        return x;
      }

      // Compound versions of the hashing algorithm I whipped together.
      uint hash( uvec2 v ) { return hash( v.x ^ hash(v.y)                         ); }
      uint hash( uvec3 v ) { return hash( v.x ^ hash(v.y) ^ hash(v.z)             ); }
      uint hash( uvec4 v ) { return hash( v.x ^ hash(v.y) ^ hash(v.z) ^ hash(v.w) ); }

      // Construct a float with half-open range [0:1] using low 23 bits.
      // All zeroes yields 0.0, all ones yields the next smallest representable value below 1.0.
      float floatConstruct( uint m ) {
        const uint ieeeMantissa = 0x007FFFFFu; // binary32 mantissa bitmask
        const uint ieeeOne      = 0x3F800000u; // 1.0 in IEEE binary32
        m &= ieeeMantissa;                     // Keep only mantissa bits (fractional part)
        m |= ieeeOne;                          // Add fractional part to 1.0
        float  f = uintBitsToFloat( m );       // Range [1:2]
        return f - 1.0;                        // Range [0:1]
      }

      // Pseudo-random value in half-open range [0:1].
      float randomBase( float x ) { return floatConstruct(hash(floatBitsToUint(x))); }
      float randomBase( vec2  v ) { return floatConstruct(hash(floatBitsToUint(v))); }
      float randomBase( vec3  v ) { return floatConstruct(hash(floatBitsToUint(v))); }
      float randomBase( vec4  v ) { return floatConstruct(hash(floatBitsToUint(v))); }
      float rand(float seed) {
        float result = randomBase(vec3(gl_FragCoord.xy, seed));
        return result;
      }

      const float F3 =  0.3333333;
      const float G3 =  0.1666667;

      float snoise(vec3 p) {
        vec3 s = floor(p + dot(p, vec3(F3)));
        vec3 x = p - s + dot(s, vec3(G3));
        vec3 e = step(vec3(0.0), x - x.yzx);
        vec3 i1 = e*(1.0 - e.zxy);
        vec3 i2 = 1.0 - e.zxy*(1.0 - e);
        vec3 x1 = x - i1 + G3;
        vec3 x2 = x - i2 + 2.0*G3;
        vec3 x3 = x - 1.0 + 3.0*G3;
        vec4 w, d;
        w.x = dot(x, x);
        w.y = dot(x1, x1);
        w.z = dot(x2, x2);
        w.w = dot(x3, x3);
        w = max(0.6 - w, 0.0);
        d.x = dot(random3(s), x);
        d.y = dot(random3(s + i1), x1);
        d.z = dot(random3(s + i2), x2);
        d.w = dot(random3(s + 1.0), x3);
        w *= w;
        w *= w;
        d *= w;
        return dot(d, vec4(52.0));
      }

      float snoiseFractal(vec3 m) {
        return 0.5333333* snoise(m)
              +0.2666667* snoise(2.0*m)
              +0.1333333* snoise(4.0*m)
              +0.0666667* snoise(8.0*m);
      }\n` + shader.fragmentShader

      // Remove transmission
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <transmission_pars_fragment>',
        /*glsl*/ `
        #ifdef USE_TRANSMISSION
          // Transmission code is based on glTF-Sampler-Viewer
          // https://github.com/KhronosGroup/glTF-Sample-Viewer
          uniform float _transmission;
          uniform float thickness;
          uniform float attenuationDistance;
          uniform vec3 attenuationColor;
          #ifdef USE_TRANSMISSIONMAP
            uniform sampler2D transmissionMap;
          #endif
          #ifdef USE_THICKNESSMAP
            uniform sampler2D thicknessMap;
          #endif
          uniform vec2 transmissionSamplerSize;
          uniform sampler2D transmissionSamplerMap;
          uniform mat4 modelMatrix;
          uniform mat4 projectionMatrix;
          varying vec3 vWorldPosition;
          vec3 getVolumeTransmissionRay( const in vec3 n, const in vec3 v, const in float thickness, const in float ior, const in mat4 modelMatrix ) {
            // Direction of refracted light.
            vec3 refractionVector = refract( - v, normalize( n ), 1.0 / ior );
            // Compute rotation-independant scaling of the model matrix.
            vec3 modelScale;
            modelScale.x = length( vec3( modelMatrix[ 0 ].xyz ) );
            modelScale.y = length( vec3( modelMatrix[ 1 ].xyz ) );
            modelScale.z = length( vec3( modelMatrix[ 2 ].xyz ) );
            // The thickness is specified in local space.
            return normalize( refractionVector ) * thickness * modelScale;
          }
          float applyIorToRoughness( const in float roughness, const in float ior ) {
            // Scale roughness with IOR so that an IOR of 1.0 results in no microfacet refraction and
            // an IOR of 1.5 results in the default amount of microfacet refraction.
            return roughness * clamp( ior * 2.0 - 2.0, 0.0, 1.0 );
          }
          vec4 getTransmissionSample( const in vec2 fragCoord, const in float roughness, const in float ior ) {
            float framebufferLod = log2( transmissionSamplerSize.x ) * applyIorToRoughness( roughness, ior );            
            #ifdef USE_SAMPLER
              #ifdef texture2DLodEXT
                return texture2DLodEXT(transmissionSamplerMap, fragCoord.xy, framebufferLod);
              #else
                return texture2D(transmissionSamplerMap, fragCoord.xy, framebufferLod);
              #endif
            #else
              return texture2D(buffer, fragCoord.xy);
            #endif
          }
          vec3 applyVolumeAttenuation( const in vec3 radiance, const in float transmissionDistance, const in vec3 attenuationColor, const in float attenuationDistance ) {
            if ( isinf( attenuationDistance ) ) {
              // Attenuation distance is +∞, i.e. the transmitted color is not attenuated at all.
              return radiance;
            } else {
              // Compute light attenuation using Beer's law.
              vec3 attenuationCoefficient = -log( attenuationColor ) / attenuationDistance;
              vec3 transmittance = exp( - attenuationCoefficient * transmissionDistance ); // Beer's law
              return transmittance * radiance;
            }
          }
          vec4 getIBLVolumeRefraction( const in vec3 n, const in vec3 v, const in float roughness, const in vec3 diffuseColor,
            const in vec3 specularColor, const in float specularF90, const in vec3 position, const in mat4 modelMatrix,
            const in mat4 viewMatrix, const in mat4 projMatrix, const in float ior, const in float thickness,
            const in vec3 attenuationColor, const in float attenuationDistance ) {
            vec3 transmissionRay = getVolumeTransmissionRay( n, v, thickness, ior, modelMatrix );
            vec3 refractedRayExit = position + transmissionRay;
            // Project refracted vector on the framebuffer, while mapping to normalized device coordinates.
            vec4 ndcPos = projMatrix * viewMatrix * vec4( refractedRayExit, 1.0 );
            vec2 refractionCoords = ndcPos.xy / ndcPos.w;
            refractionCoords += 1.0;
            refractionCoords /= 2.0;
            // Sample framebuffer to get pixel the refracted ray hits.
            vec4 transmittedLight = getTransmissionSample( refractionCoords, roughness, ior );
            vec3 attenuatedColor = applyVolumeAttenuation( transmittedLight.rgb, length( transmissionRay ), attenuationColor, attenuationDistance );
            // Get the specular component.
            vec3 F = EnvironmentBRDF( n, v, specularColor, specularF90, roughness );
            return vec4( ( 1.0 - F ) * attenuatedColor * diffuseColor, transmittedLight.a );
          }
        #endif\n`
      )

      // Add refraction
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <transmission_fragment>',
        /*glsl*/ `  
        // Improve the refraction to use the world pos
        material.transmission = _transmission;
        material.transmissionAlpha = 1.0;
        material.thickness = thickness;
        material.attenuationDistance = attenuationDistance;
        material.attenuationColor = attenuationColor;
        #ifdef USE_TRANSMISSIONMAP
          material.transmission *= texture2D( transmissionMap, vUv ).r;
        #endif
        #ifdef USE_THICKNESSMAP
          material.thickness *= texture2D( thicknessMap, vUv ).g;
        #endif
        
        vec3 pos = vWorldPosition;
        float runningSeed = 0.0;
        vec3 v = normalize( cameraPosition - pos );
        vec3 n = inverseTransformDirection( normal, viewMatrix );
        vec3 transmission = vec3(0.0);
        float transmissionR, transmissionB, transmissionG;
        float randomCoords = rand(runningSeed++);
        float thickness_smear = thickness * max(pow(roughnessFactor, 0.33), anisotropicBlur);
        vec3 distortionNormal = vec3(0.0);
        vec3 temporalOffset = vec3(time, -time, -time) * temporalDistortion;
        if (distortion > 0.0) {
          distortionNormal = distortion * vec3(snoiseFractal(vec3((pos * distortionScale + temporalOffset))), snoiseFractal(vec3(pos.zxy * distortionScale - temporalOffset)), snoiseFractal(vec3(pos.yxz * distortionScale + temporalOffset)));
        }
        for (float i = 0.0; i < ${samples}.0; i ++) {
          vec3 sampleNorm = normalize(n + roughnessFactor * roughnessFactor * 2.0 * normalize(vec3(rand(runningSeed++) - 0.5, rand(runningSeed++) - 0.5, rand(runningSeed++) - 0.5)) * pow(rand(runningSeed++), 0.33) + distortionNormal);
          transmissionR = getIBLVolumeRefraction(
            sampleNorm, v, material.roughness, material.diffuseColor, material.specularColor, material.specularF90,
            pos, modelMatrix, viewMatrix, projectionMatrix, material.ior, material.thickness  + thickness_smear * (i + randomCoords) / float(${samples}),
            material.attenuationColor, material.attenuationDistance
          ).r;
          transmissionG = getIBLVolumeRefraction(
            sampleNorm, v, material.roughness, material.diffuseColor, material.specularColor, material.specularF90,
            pos, modelMatrix, viewMatrix, projectionMatrix, material.ior  * (1.0 + chromaticAberration * (i + randomCoords) / float(${samples})) , material.thickness + thickness_smear * (i + randomCoords) / float(${samples}),
            material.attenuationColor, material.attenuationDistance
          ).g;
          transmissionB = getIBLVolumeRefraction(
            sampleNorm, v, material.roughness, material.diffuseColor, material.specularColor, material.specularF90,
            pos, modelMatrix, viewMatrix, projectionMatrix, material.ior * (1.0 + 2.0 * chromaticAberration * (i + randomCoords) / float(${samples})), material.thickness + thickness_smear * (i + randomCoords) / float(${samples}),
            material.attenuationColor, material.attenuationDistance
          ).b;
          transmission.r += transmissionR;
          transmission.g += transmissionG;
          transmission.b += transmissionB;
        }
        transmission /= ${samples}.0;
        totalDiffuse = mix( totalDiffuse, transmission.rgb, material.transmission );\n`
      )
    }

    Object.keys(this.uniforms).forEach((name) =>
      Object.defineProperty(this, name, {
        get: () => this.uniforms[name].value,
        set: (v) => (this.uniforms[name].value = v),
      })
    )
  }
}

  window.PortfolioReferenceTransmission = MeshTransmissionMaterialImpl;
})();

/* Portfolio adaptation of pmndrs' Best Served Bold Christmas Baubles.
 * The locally bundled runtime exposes React, Fiber, Drei and Rapier.
 * Assets are embedded data URLs so this also works when opened via file://.
 */
(function () {
  'use strict';
  const R = window.PortfolioR3F;
  const { React, h, Canvas, useFrame, useGLTF, useEnvironment, Environment,
    Physics, RigidBody, BallCollider, CylinderCollider, Vector3,
    MeshStandardMaterial, MeshPhysicalMaterial, SphereGeometry,
    EffectComposer, ToneMapping, N8AO, ToneMappingMode } = R;
  const assets = window.PortfolioBaubleAssets;
  const root = document.getElementById('baubles-root');
  if (!root) return;
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const material = new MeshStandardMaterial({ color: '#c0a0a0', emissive: 'red' });
  const capMaterial = new MeshPhysicalMaterial({ metalness: .75, roughness: .15,
    color: '#8a492f', emissive: '#600000', envMapIntensity: 20 });
  // Preserve the original pink finish; change only alternating ornaments.
  const filmCanvas = document.createElement('canvas');
  filmCanvas.width = 256; filmCanvas.height = 128;
  const filmContext = filmCanvas.getContext('2d');
  const pixels = filmContext.createImageData(256,128);
  for(let y=0;y<128;y++) for(let x=0;x<256;x++) {
    const wave=.5+.5*Math.sin(x/256*Math.PI*5 + y/128*Math.PI*2 + .9*Math.sin(y/128*Math.PI*4));
    const p=(y*256+x)*4;
    pixels.data[p]=pixels.data[p+1]=pixels.data[p+2]=Math.round(wave*255);
    pixels.data[p+3]=255;
  }
  filmContext.putImageData(pixels,0,0);
  const filmMap = new R.CanvasTexture(filmCanvas);
  filmMap.wrapS=1000;
  const makeGlassMaterial = window.PortfolioMakeGlassMaterial = (colour, index) => {
    const mat = new window.PortfolioReferenceTransmission(3, false);
    mat.color.set(colour);
    mat.roughness=.035; mat.metalness=0;
    mat.ior=1.43; mat.thickness=1.85; mat._transmission=.99;
    mat.reflectivity=.5; mat.envMapIntensity=.95;
    mat.clearcoat=.5; mat.clearcoatRoughness=.025;
    mat.iridescence=.4; mat.iridescenceIOR=1.3;
    mat.iridescenceThicknessRange=[200,520]; mat.iridescenceThicknessMap=filmMap;
    mat.chromaticAberration=.045; mat.anisotropicBlur=.025;
    mat.attenuationColor.set(colour); mat.attenuationDistance=4;
    if (index === 0) {
      // Colourless glass: neutral transmission, no blue absorption.
      mat.attenuationColor.set('#ffffff'); mat.attenuationDistance=Infinity;
      mat.roughness=.015; mat.iridescence=.06; mat.chromaticAberration=.012;
    }
    mat.userData.portfolioGlass=true;
    return mat;
  };
  const glassMaterials = ['#ffffff','#ac87ef'].map(makeGlassMaterial);
  const glassCap = new R.GlassPhysicalMaterial({color:'#dbe7f5',metalness:.95,roughness:.14,envMapIntensity:1.6});
  const geometry = new SphereGeometry(1, 48, 36);
  // Stable initial conditions: a compact cluster settles into zero gravity.
  const ornaments = Array.from({ length: window.innerWidth < 600 ? 32 : 50 }, (_, i) => {
    const random = (n) => { const v = Math.sin((i + 1) * n) * 43758.5453; return v - Math.floor(v); };
    return { above: i % 9 === 0, side: Math.floor(i / 2) % 2 === 0 ? -1 : 1, glassIndex: i % 2 === 0 ? (Math.floor(i/2)%2) : -1, scale: [.75, .75, 1, 1, 1.25][Math.floor(random(12.98) * 5)],
      position: [(random(78.23) - .5) * 12, (random(39.43) - .5) * 12 - 6,
        (random(93.11) - .5) * 12 - 6] };
  });

  function Bauble({ scale, position, glassIndex, side, above }) {
    const isGlass = glassIndex >= 0;
    const { nodes } = useGLTF(assets.cap);
    const envMap = useEnvironment({ files: assets.environment });
    const glassEnvMap = useEnvironment({ files: assets.glassEnvironment });
    const body = React.useRef(null);
    const force = React.useMemo(() => new Vector3(), []);
    const scattered = React.useRef(false);
    useFrame(({viewport}, delta) => {
      if (!body.current) return;
      const dt = Math.min(.05, delta);
      const badge=window.PortfolioLanyardState;
      if (!badge || badge.elapsed < .65) {
        body.current.applyImpulse(force.copy(body.current.translation()).normalize()
          .multiply({ x: -50 * dt * scale, y: -150 * dt * scale, z: -50 * dt * scale }), false);
        return;
      }
      const p=body.current.translation();
      const progress=Math.min(1,Math.max(0,(badge.elapsed-.65)/1.45));
      const clearance=(badge.world?.w || 1.8)+.55;
      const targetX=above ? side*(.8+scale*.25)*progress : side*(clearance+Math.min(2.5,viewport.width*.12))*progress;
      const targetY=above ? Math.min(viewport.height/2-scale-.25,(badge.world?.y || 0)+(badge.world?.h || 2.5)+scale+.7) : Math.max(-1.0,Math.min(.8,badge.world?.y || 0));
      if(!scattered.current && badge.elapsed>.9){
        body.current.applyImpulse({x:side*4.2*scale,y:.6*scale,z:-2*scale},true);
        scattered.current=true;
      }
      force.set((targetX-p.x)*12,(targetY-p.y)*13,(-2.5-p.z)*8);
      if(Math.abs(p.x)<clearance+scale && Math.abs(p.y-(badge.world?.y || 0))<(badge.world?.h || 2.5)+scale)
        force.x+=side*(clearance+scale-Math.abs(p.x))*32*progress;
      force.clampLength(0,150).multiplyScalar(dt*scale);
      body.current.applyImpulse(force,true);
    });
    return h(RigidBody, { ref: body, position, colliders: false,
      linearDamping: .75, angularDamping: .15, friction: .2 },
      h(BallCollider, { args: [scale] }),
      h(CylinderCollider, { rotation: [Math.PI / 2, 0, 0],
        position: [0, 0, 1.2 * scale], args: [.15 * scale, .275 * scale] }),
      h('mesh', { name: isGlass ? 'ice-glass-bauble' : 'pink-bauble', castShadow: !isGlass, receiveShadow: !isGlass, scale, geometry, material: isGlass ? glassMaterials[glassIndex] : material, ...(isGlass ? {'material-envMap': glassEnvMap} : {}) }),
      h('mesh', { castShadow: true, scale: 2.5 * scale,
        position: [0, 0, -1.8 * scale], geometry: nodes.Mesh_1.geometry,
        material: isGlass ? glassCap : capMaterial, 'material-envMap': isGlass ? glassEnvMap : envMap }));
  }

/* Shared refraction capture for the glass ornaments. The CSS background stays
 * untouched; its colours and square spacing are mirrored only inside glass. */
function GlassRefraction() {
  const backplate = React.useRef(null);
  const capture = React.useMemo(() => new R.WebGLRenderTarget(640, 400, {
    type: R.HalfFloatType, depthBuffer: true
  }), []);
  const uniforms = React.useMemo(() => ({
    uScreen: { value: [1, 1] },
    uHeroHeight: { value: 1 },
    uOffset: { value: 80 },
    uPitch: { value: 9 }
  }), []);
  React.useEffect(() => () => capture.dispose(), [capture]);
  useFrame(({ gl, scene, camera, size }, delta) => {
    if (!backplate.current) return;
    const hero = root.parentElement.getBoundingClientRect();
    const canvasRect = root.getBoundingClientRect();
    const width = Math.min(window.innerWidth < 600 ? 384 : 768, Math.round(size.width));
    const height = Math.max(128, Math.round(width * size.height / size.width));
    if (capture.width !== width || capture.height !== height) capture.setSize(width, height);
    uniforms.uScreen.value = [size.width, size.height];
    uniforms.uHeroHeight.value = hero.height;
    uniforms.uOffset.value = canvasRect.top - hero.top;
    const surfaces = [];
    scene.traverse(object => {
      if (object.isMesh && object.material?.userData.portfolioGlass && object.visible) {
        surfaces.push(object);
      }
    });
    if (!surfaces.length) return;
    const oldTarget = gl.getRenderTarget();
    const oldMapping = gl.toneMapping;
    const oldXr = gl.xr.enabled;
    const oldAutoClear = gl.autoClear;
    try {
      gl.xr.enabled = false;
      gl.toneMapping = 0;
      gl.autoClear = true;
      surfaces.forEach(mesh => { mesh.visible = false; });
      backplate.current.visible = true;
      gl.setRenderTarget(capture);
      gl.clear();
      gl.render(scene, camera);
      glassMaterials.forEach(mat => {
        mat.buffer = capture.texture;
        if (!reducedMotion) mat.time += Math.min(delta, .08);
      });
    } finally {
      backplate.current.visible = false;
      surfaces.forEach(mesh => { mesh.visible = true; });
      gl.setRenderTarget(oldTarget);
      gl.toneMapping = oldMapping;
      gl.xr.enabled = oldXr;
      gl.autoClear = oldAutoClear;
    }
  });
  return h('mesh', { ref: backplate, visible: false, frustumCulled: false,
    renderOrder: -100 }, h('planeGeometry', { args: [2, 2] }),
    h('shaderMaterial', { uniforms, depthWrite: false, depthTest: false,
      toneMapped: false,
      vertexShader: `varying vec2 vScreen;
        void main() { vScreen = uv; gl_Position = vec4(position.xy, .999, 1.0); }`,
      fragmentShader: `varying vec2 vScreen;
        uniform vec2 uScreen;
        uniform float uHeroHeight, uOffset, uPitch;
        vec3 linearColour(vec3 c) {
          return mix(c/12.92, pow((c+.055)/1.055, vec3(2.4)), step(vec3(.04045), c));
        }
        void main() {
          vec2 pixel = vec2(vScreen.x*uScreen.x, (1.0-vScreen.y)*uScreen.y+uOffset);
          float y = clamp(pixel.y / (uHeroHeight*.85), 0.0, 1.0);
          vec3 colour = mix(vec3(230.,234.,245.)/255., vec3(246.)/255., y);
          vec2 tile = mod(pixel, uPitch);
          float square = (1.0-step(uPitch*.5,tile.x)) * (1.0-step(uPitch*.5,tile.y));
          colour = mix(colour, vec3(1.), square*.30);
          gl_FragColor = vec4(linearColour(colour), 1.0);
        }`
    }));
}

  function BadgeCollider() {
    const body = React.useRef(null);
    const collider = React.useRef(null);
    useFrame(({ viewport }) => {
      const badge = window.PortfolioLanyardState;
      if (!body.current || !badge) return;
      const frame = root.getBoundingClientRect();
      const x = ((badge.x - frame.left) / frame.width - .5) * viewport.width;
      const y = (.5 - (badge.y - frame.top) / frame.height) * viewport.height;
      const w = badge.width / frame.width * viewport.width / 2;
      const hh = badge.height / frame.height * viewport.height / 2;
      badge.world = { x, y, w, h: hh };
      if (collider.current) collider.current.setHalfExtents({ x: w + .16, y: hh + .12, z: 3 });
      body.current.setNextKinematicTranslation({ x, y, z: -1 });
      body.current.setNextKinematicRotation({ x: 0, y: 0, z: Math.sin(badge.angle / 2), w: Math.cos(badge.angle / 2) });
    });
    return h(RigidBody, { ref: body, type: 'kinematicPosition', colliders: false,
      position: [0, 100, 0] }, h(R.CuboidCollider, { ref: collider, args: [1.7, 2.4, 3], restitution: .65 }));
  }

  function Pointer() {
    const body = React.useRef(null);
    const position = React.useMemo(() => new Vector3(100, 100, 100), []);
    useFrame(({ pointer, viewport }, delta) => {
      if (!root.closest('main').matches(':hover') || window.PortfolioHeroPointer?.overBadge || window.matchMedia('(pointer: coarse)').matches) {
        body.current?.setNextKinematicTranslation({ x: 100, y: 100, z: 100 });
        return;
      }
      const screenPointer=window.PortfolioHeroPointer;
      const bounds=root.getBoundingClientRect();
      const px=screenPointer ? ((screenPointer.x-bounds.left)/bounds.width*2-1) : pointer.x;
      const py=screenPointer ? (1-(screenPointer.y-bounds.top)/bounds.height*2) : pointer.y;
      position.lerp({ x: px * viewport.width / 2, y: py * viewport.height / 2, z: 0 },
        1 - Math.exp(-13 * delta));
      body.current?.setNextKinematicTranslation(position);
    });
    return h(RigidBody, { ref: body, position: [100, 100, 100],
      type: 'kinematicPosition', colliders: false }, h(BallCollider, { args: [2] }));
  }

  function Ready() {
    React.useEffect(() => {
      root.parentElement.classList.add('baubles-loaded');
      root.dataset.ready = 'true';
      root.dataset.glassCount = String(ornaments.filter(o=>o.glassIndex>=0).length);
      root.dataset.pinkCount = String(ornaments.filter(o=>o.glassIndex<0).length);
    }, []);
    return null;
  }

  function App() {
    const [visible, setVisible] = React.useState(true);
    const [paused, setPaused] = React.useState(false);
    const [settled, setSettled] = React.useState(false);
    React.useEffect(() => {
      const hero = root.closest('main');
      const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting));
      observer.observe(hero);
      const onVisibility = () => setVisible(!document.hidden && hero.getBoundingClientRect().bottom > 0);
      document.addEventListener('visibilitychange', onVisibility);
      const timer = setTimeout(() => setSettled(true), 4000);
      const toggle = document.getElementById('baubles-pause');
      const onToggle = () => setPaused((value) => !value);
      toggle.addEventListener('click', onToggle);
      return () => { observer.disconnect(); clearTimeout(timer);
        document.removeEventListener('visibilitychange', onVisibility);
        toggle.removeEventListener('click', onToggle); };
    }, []);
    const isPaused = paused || (reducedMotion && settled);
    window.PortfolioMotionPaused = isPaused;
    React.useEffect(() => {
      const toggle = document.getElementById('baubles-pause');
      toggle.textContent = paused ? '播放动效 ↗' : '暂停动效 Ⅱ';
      toggle.setAttribute('aria-pressed', String(paused));
    }, [paused]);
    return h(Canvas, { shadows: true, dpr: [1, 1.5], frameloop: visible && !isPaused ? 'always' : 'never',
      gl: { alpha: true, stencil: false, depth: true, antialias: true },
      camera: { position: [0, 0, 20], fov: window.innerWidth < 600 ? 45 : 36, near: 1, far: 100 },
      onCreated: ({ gl }) => { gl.toneMappingExposure = 1.5; } },
      h(React.Suspense, { fallback: null },
        h('ambientLight', { intensity: Math.PI }),
        h('spotLight', { position: [20, 20, 25], intensity: Math.PI, decay: 0,
          penumbra: 1, angle: .2, color: 'white', castShadow: true, 'shadow-mapSize': [512, 512] }),
        h('directionalLight', { position: [0, 5, -4], intensity: 4 * Math.PI }),
        h('directionalLight', { position: [0, -15, 0], intensity: 4 * Math.PI, color: 'red' }),
        h(Physics, { gravity: [0, 0, 0], paused: !visible || isPaused },
          h(Pointer), h(BadgeCollider), ornaments.map((props, i) => h(Bauble, { key: i, ...props }))),
        h(Environment, { files: assets.environment }),
        h(GlassRefraction),
        h(EffectComposer, null,
          h(ToneMapping, { mode: ToneMappingMode.ACES_FILMIC }),
          h(N8AO, { color: 'red', aoRadius: 2, distanceFalloff: 2.5, intensity: 1 })),
        h(Ready)));
  }
  class SceneBoundary extends React.Component {
    constructor(props) { super(props); this.state = { failed: false }; }
    static getDerivedStateFromError() { return { failed: true }; }
    componentDidCatch(error) { console.error('Portfolio 3D scene:', error); }
    render() { return this.state.failed ? null : this.props.children; }
  }
  R.createRoot(root).render(h(SceneBoundary, null, h(App)));
})();
;
/* Reuse the bauble's physical transmission shader and studio HDR for the eyes. */
(function () {
  'use strict';
  const R = window.PortfolioR3F;
  const { React, h, Canvas, useFrame, useEnvironment, Environment } = R;
  const assets = window.PortfolioBaubleAssets;
  if (!R || !window.PortfolioMakeGlassMaterial) return;

  function EyeSphere() {
    const environment = useEnvironment({ files: assets.glassEnvironment });
    const surface = React.useMemo(() => {
      const material = window.PortfolioMakeGlassMaterial('#f2f7ff', 0);
      // A thicker, softly frosted body rather than an almost invisible bubble.
      material._transmission = .48;
      material.thickness = 2.5;
      material.roughness = .13;
      material.anisotropicBlur = .08;
      material.clearcoat = 1;
      material.clearcoatRoughness = .035;
      material.iridescence = .08;
      material.envMapIntensity = 1.2;
      const canvas = document.createElement('canvas');
      canvas.width = canvas.height = 256;
      const ctx = canvas.getContext('2d');
      const background = ctx.createLinearGradient(0, 0, 256, 256);
      background.addColorStop(0, '#d8f3ff');
      background.addColorStop(.55, '#8dd5f0');
      background.addColorStop(1, '#d2e2f2');
      ctx.fillStyle = background;
      ctx.fillRect(0, 0, 256, 256);
      const texture = new R.CanvasTexture(canvas);
      material.buffer = texture;
      return { material, texture };
    }, []);
    React.useEffect(() => () => {
      surface.material.dispose(); surface.texture.dispose();
    }, [surface]);
    useFrame((_, delta) => { surface.material.time += Math.min(delta, .08); });
    return h(React.Fragment, null,
      h('ambientLight', { intensity: .45 }),
      h('directionalLight', { position: [-3, 4, 5], intensity: 2.2 }),
      h('mesh', { material: surface.material, 'material-envMap': environment },
        h('sphereGeometry', { args: [1, 64, 48] })),
      h(Environment, { files: assets.glassEnvironment }));
  }
  function EyeApp() {
    const [visible, setVisible] = React.useState(false);
    React.useEffect(() => {
      const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting));
      observer.observe(document.getElementById('cta-section'));
      return () => observer.disconnect();
    }, []);
    return h(Canvas, { dpr: [1, 1.5], frameloop: visible ? 'always' : 'never',
      camera: { position: [0, 0, 4], fov: 30, near: .1, far: 20 },
      gl: { alpha: true, antialias: true },
      onCreated: ({ gl }) => { gl.toneMappingExposure = 1; } },
      h(React.Suspense, { fallback: null }, h(EyeSphere)));
  }
  document.querySelectorAll('.cta-eye-shell').forEach(shell => {
    shell.classList.add('cta-eye-three');
    const mount = document.createElement('div');
    mount.className = 'cta-eye-three-root';
    mount.setAttribute('aria-hidden', 'true');
    shell.prepend(mount);
    R.createRoot(mount).render(h(EyeApp));
  });
})();
